/// Number of pre-allocated supply pickups (fixed at build; the renderer scene can't grow).
const N_PICKUPS: usize = 14;
/// Tiger I road-fuel capacity. Campaign fuel is already tracked in litres, so a physical can feeds
/// the same live meter instead of creating a second abstract "fuel pickup" currency.
const TIGER_FUEL_CAPACITY_L: f32 = 540.0;
const PORTABLE_REACH_M: f32 = 2.2;
const TIGER_REAR_SERVICE_REACH_M: f32 = 2.25;
const PORTABLE_REFUEL_PROMPT: &str = "AM HECK: KANISTER EINFÜLLEN [E]";
const N_MAP_CASES: usize = crate::run_route::ROUTE_SITE_COUNT;

fn format_portable_refuel_prompt(can_liters: f32, accepted_liters: f32) -> String {
    let can_liters = can_liters.max(0.0);
    let accepted_liters = accepted_liters.max(0.0).min(can_liters);
    if accepted_liters + 0.05 < can_liters {
        format!("AM HECK: {accepted_liters:.1} L EINFÜLLEN · {can_liters:.1} L IM KANISTER [E]")
    } else {
        format!("AM HECK: {can_liters:.1} L EINFÜLLEN [E]")
    }
}

fn accepted_portable_fuel_liters(tank_fuel_liters: Option<f32>, can_liters: f32) -> f32 {
    tank_fuel_liters.map_or(0.0, |tank_fuel_liters| {
        (TIGER_FUEL_CAPACITY_L - tank_fuel_liters)
            .max(0.0)
            .min(can_liters.max(0.0))
    })
}

/// Service is spatial: the soldier must be behind the rear plate, not merely beside any point on
/// the Tiger. Kept in hull-local space so slopes and heading cannot move the legal refuel zone.
fn tiger_rear_service_local(local: Vec3) -> bool {
    local.z < -2.25 && Vec2::new(local.x, local.z + 3.35).length() <= TIGER_REAR_SERVICE_REACH_M
}

// Act II's Oderbruch waterway is part of the navigation rules, not backdrop.  These values mirror
// the authored channel in tools/worldgen/gen_world.py.  The heightfield supplies the banks, while
// this small deterministic navigation mask prevents tracked vehicles and dismounted crew from
// treating the channel bottom as an alternate road.  The sole legal aperture is the 48 m bridge at
// z=500; while an actor is on it, the deck replaces the carved-channel height as walkable ground.
const ACT2_CHANNEL_X_M: f32 = 0.0;
const ACT2_CHANNEL_MEANDER_M: f32 = 40.0;
const ACT2_CHANNEL_MEANDER_SCALE_M: f32 = 700.0;
const ACT2_BRIDGE_Z_M: f32 = 500.0;
const ACT2_CHANNEL_NO_GO_HALF_M: f32 = 15.0;
const ACT2_BRIDGE_HALF_LENGTH_M: f32 = 24.0;
const ACT2_BRIDGE_LANE_HALF_M: f32 = 4.5;

fn act2_channel_center_x(z: f32) -> f32 {
    ACT2_CHANNEL_X_M
        + ACT2_CHANNEL_MEANDER_M * ((z - ACT2_BRIDGE_Z_M) / ACT2_CHANNEL_MEANDER_SCALE_M).sin()
}

fn act2_bridge_lane(z: f32) -> bool {
    (z - ACT2_BRIDGE_Z_M).abs() <= ACT2_BRIDGE_LANE_HALF_M
}

/// Resolve one XZ movement step against the continuous Act II channel.  Movement along either bank
/// is retained (only the channel-normal component is removed), so contact does not feel like an
/// invisible full stop.  Entering through the authored bridge lane remains untouched.
fn constrain_act2_channel_step(from: Vec2, to: Vec2) -> Vec2 {
    if act2_bridge_lane(to.y) {
        return to;
    }
    let from_side = from.x - act2_channel_center_x(from.y);
    let to_center = act2_channel_center_x(to.y);
    let to_side = to.x - to_center;
    if to_side.abs() >= ACT2_CHANNEL_NO_GO_HALF_M {
        return to;
    }
    let bank_sign = if from_side.abs() > 0.05 {
        from_side.signum()
    } else if to_side.abs() > 0.05 {
        to_side.signum()
    } else {
        1.0
    };
    Vec2::new(to_center + bank_sign * ACT2_CHANNEL_NO_GO_HALF_M, to.y)
}

fn act2_step_crosses_bridge(from: Vec2, to: Vec2) -> bool {
    let from_side = from.x - act2_channel_center_x(from.y);
    let to_side = to.x - act2_channel_center_x(to.y);
    if from_side.abs() <= 0.001 || to_side.abs() <= 0.001 || from_side.signum() == to_side.signum()
    {
        return false;
    }
    let t = from_side / (from_side - to_side);
    let crossing_z = from.y + (to.y - from.y) * t.clamp(0.0, 1.0);
    act2_bridge_lane(crossing_z)
}

fn act2_bridge_deck_height(hf: &Heightfield, pos: Vec2) -> Option<f32> {
    if pos.x.abs() > ACT2_BRIDGE_HALF_LENGTH_M || !act2_bridge_lane(pos.y) {
        return None;
    }
    // The generator lays its slabs 0.1 m above the higher of the two sampled banks.
    Some(
        hf.height_at(-30.0, ACT2_BRIDGE_Z_M)
            .max(hf.height_at(30.0, ACT2_BRIDGE_Z_M))
            + 0.1,
    )
}

