const HOT_FRAGMENT_WHIZZ_MIN_SPEED: f32 = 2.4;
const HOT_FRAGMENT_WHIZZ_RADIUS: f32 = 0.62;
/// Space the two little metal contacts apart so they remain individual dings after cabin reverb.
const HOT_FRAGMENT_AUDIO_CADENCE: f32 = 0.22;
const HOT_FRAGMENT_AUDIO_VOLUME: f32 = 0.34;
const HOT_FRAGMENT_WHIZZ_CADENCE: f32 = 0.12;
const HOT_FRAGMENT_WHIZZ_VOLUME: f32 = 0.48;
const CARRY_WALK_SLOW: f32 = 0.72; // walk-speed factor while lugging a round
const N_CASING: usize = 4; // pooled rigid-body shell casings (round-robin)
const N_LAMP: usize = 4; // interior annunciator lamps (fire / breech / repair / station)

/// The posted crew STATION the one player is manning. Maps 1:1 onto `CrewRole` for the damage gates.
#[derive(Copy, Clone, PartialEq, Eq, Debug)]
pub enum Station {
    Gunner,
    Loader,
    Driver,
    Radioman,
    Commander,
}

impl Station {
    /// The driver rides the HULL; gunner/loader/commander ride the TURRET. A turret↔hull move costs
    /// more (clambering through the basket) than a within-turret shuffle.
    fn in_hull(self) -> bool {
        matches!(self, Station::Driver | Station::Radioman)
    }
}

/// View-local weather shelter, separate from the physical precipitation gate. Depth is the final
/// authority: armor in front of the eye blocks every field layer, while a real hatch/optic opening
/// exposes distant scene depth and therefore distant snow. An open cupola viewed from inside admits
/// a little mid-distance weather but never paints flakes onto the nearby steel compartment.
fn tank_weather_shelter(station: Station, exposed: bool, hatch_open: bool) -> f32 {
    if exposed {
        0.0
    } else if hatch_open && matches!(station, Station::Commander | Station::Loader) {
        0.68
    } else {
        1.0
    }
}

/// Cost (seconds) of a station change — compartment-aware.
fn switch_cost(a: Station, b: Station) -> f32 {
    if a.in_hull() != b.in_hull() {
        SWITCH_HULL
    } else {
        SWITCH_TURRET
    }
}

/// Ram progress added per Space mash, degraded when the loader is down.
fn ram_per_press(loader_ok: bool) -> f32 {
    if loader_ok {
        RAM_PER_PRESS_OK
    } else {
        RAM_PER_PRESS_KO
    }
}

/// Main-gun breech state (player only). `Spent` = fired, hot casing still in the gun; `Empty` =
/// casing out, no round; `Loaded` = a round is seated and the gun can fire.
#[derive(Copy, Clone, PartialEq, Eq, Debug)]
enum Breech {
    Loaded,
    Spent,
    Empty,
}

/// A discrete tactile emergency the player is mid-way through — it suppresses ALL station controls
/// while it runs ("both hands full"). Reload (eject/ram) is a Loader-STATION duty, not an Activity,
/// so the aim↔reload triage is enforced by the station switch, not by locking out the seat.
#[derive(Copy, Clone, PartialEq, Eq, Debug)]
enum Activity {
    Extinguish,
    Repair(ModuleKind),
}

/// Which downed modules are a sane field-fix, the station that reaches them, and how long (exposed)
/// it takes. `None` = battle-destroyed / catastrophic, never repairable in the field.
fn repair_time(k: ModuleKind) -> Option<f32> {
    use ModuleKind::*;
    match k {
        LeftTrack | RightTrack => Some(8.0), // thrown track — re-set it, but hatch-out + stationary
        Transmission => Some(7.0),
        TurretTraverse => Some(3.0),  // clear a jam
        Radio => Some(2.0),           // reconnect
        CoaxMg | HullMg => Some(1.6), // clear a stoppage
        _ => None,                    // MainGun / GunnerSight / Engine / Fuel / AmmoRack: no
    }
}

/// One pooled rigid-body shell casing: ejected from the breech, tumbles + falls under gravity, bounces
/// once off the turret floor, clatters. Reuses the turret-pop / spark integration style. No rand.
#[derive(Clone, Default)]
struct Casing {
    active: bool,
    pos: Vec3,
    vel: Vec3,
    spin_axis: Vec3,
    ang: f32,
    spin: f32,
    t: f32, // life remaining
    bounced: bool,
    floor_y: f32, // world Y of the turret-floor bounce plane
    /// Riding the loader's hands (just pulled from the breech): physics + retirement paused;
    /// `drive_casings` draws it at the carry transform until the toss releases it.
    carried: bool,
}

/// The two surviving Tigers which join the player for Halbe. They are deliberately lightweight
/// compared with the player's embodied machine: formation driving and a slow, visible gun cycle are
/// enough to make the last stand a platoon action instead of another solitary arena.
#[derive(Clone)]
struct AllyTiger {
    tank: Tank,
    fire_cd: f32,
    formation_side: f32,
}

#[derive(Clone)]
struct CampaignHulk {
    kind: EnemyKind,
    models: [Mat4; 3],
    ember: f32,
    burning: bool,
}

/// Read-only ground-plane state used by the policy-preserving vehicle safety layer. IDs are stable
/// enemy indices; `usize::MAX` is reserved for the player Tiger, so direct-ahead ties always choose
/// the same opposite steering sides for an enemy pair.
#[derive(Clone, Copy, Debug)]
struct VehicleMotion {
    id: usize,
    footprint: tank::HullFootprint,
    velocity: Vec2,
}

#[derive(Clone, Copy, Debug)]
struct VehiclePairResolution {
    a_delta: Vec2,
    b_delta: Vec2,
    closing: bool,
}

fn tank_velocity_xz(vehicle: &Tank) -> Vec2 {
    let forward = vehicle.forward();
    Vec2::new(forward.x, forward.z) * vehicle.speed
}

fn vehicle_motion(id: usize, vehicle: &Tank) -> VehicleMotion {
    VehicleMotion {
        id,
        footprint: vehicle.hull_footprint(),
        velocity: tank_velocity_xz(vehicle),
    }
}

fn enemy_mass_tonnes(kind: EnemyKind) -> f32 {
    match kind {
        EnemyKind::T34 => 26.5,
        EnemyKind::Su100 => 31.6,
        EnemyKind::Kv2 => 52.0,
        EnemyKind::Isu152 => 46.0,
        EnemyKind::Is2 => 46.0,
        EnemyKind::Is3 => 46.5,
    }
}

fn vehicle_inverse_mass(vehicle: &Tank, mass_tonnes: f32) -> f32 {
    if vehicle.alive {
        1.0 / mass_tonnes.max(1.0)
    } else {
        0.0 // wrecks retain battlefield mass but are no longer powered/movable
    }
}

/// Resolve one penetrating OBB pair by inverse mass. The returned deltas move A opposite the
/// A-to-B contact normal and B along it; a zero inverse mass makes a wreck/static body immovable.
fn vehicle_pair_resolution(
    a: VehicleMotion,
    a_inverse_mass: f32,
    b: VehicleMotion,
    b_inverse_mass: f32,
) -> Option<VehiclePairResolution> {
    let contact = tank::yaw_obb_contact(a.footprint, b.footprint)?;
    let inverse_mass_sum = a_inverse_mass.max(0.0) + b_inverse_mass.max(0.0);
    if !inverse_mass_sum.is_finite() || inverse_mass_sum <= f32::EPSILON {
        return None;
    }
    let translation = contact.normal * (contact.depth + VEHICLE_CONTACT_SLOP_M);
    let a_share = a_inverse_mass.max(0.0) / inverse_mass_sum;
    let b_share = b_inverse_mass.max(0.0) / inverse_mass_sum;
    Some(VehiclePairResolution {
        a_delta: -translation * a_share,
        b_delta: translation * b_share,
        closing: (b.velocity - a.velocity).dot(contact.normal) < -0.05,
    })
}

fn footprint_support_radius(footprint: tank::HullFootprint, world_axis: Vec2) -> f32 {
    let (sin, cos) = footprint.heading.sin_cos();
    let local_x = Vec2::new(cos, -sin);
    let local_z = Vec2::new(sin, cos);
    footprint.half_extents.x * local_x.dot(world_axis).abs()
        + footprint.half_extents.y * local_z.dot(world_axis).abs()
}

/// Safety post-process for the existing 14-observation/3-action policy. It predicts closest
/// approach against nearby active hulls, then blends the proposed steer away from the strongest
/// threat and eases only throttle that is carrying the tank toward it. Fire is intentionally not
/// represented here, so the trained action/weight layout is unchanged.
fn apply_vehicle_avoidance(
    own: VehicleMotion,
    neighbors: &[VehicleMotion],
    drive: f32,
    steer: f32,
) -> (f32, f32) {
    let (sin, cos) = own.footprint.heading.sin_cos();
    let forward = Vec2::new(sin, cos);
    let local_x = Vec2::new(cos, -sin);
    // Acceleration is finite, so blend current road speed with the policy's requested target over
    // the short horizon instead of pretending a T-34 instantly reaches TOP_SPEED.
    let desired_velocity = own.velocity * 0.35 + forward * (drive * tank::TOP_SPEED * 0.65);

    let mut best: Option<(f32, usize, f32, f32)> = None; // urgency, id, avoid steer, ahead
    for neighbor in neighbors {
        if neighbor.id == own.id {
            continue;
        }
        let delta = neighbor.footprint.center - own.footprint.center;
        let distance = delta.length();
        if !distance.is_finite() || distance > VEHICLE_AVOID_NEIGHBORHOOD_M {
            continue;
        }

        let relative_velocity = neighbor.velocity - desired_velocity;
        let relative_speed_sq = relative_velocity.length_squared();
        let closest_t = if relative_speed_sq > 1.0e-5 {
            (-delta.dot(relative_velocity) / relative_speed_sq).clamp(0.0, VEHICLE_AVOID_HORIZON_S)
        } else {
            0.0
        };
        let closest_delta = delta + relative_velocity * closest_t;
        let closest_distance = closest_delta.length();
        let axis = if closest_distance > 1.0e-4 {
            closest_delta / closest_distance
        } else if distance > 1.0e-4 {
            delta / distance
        } else {
            forward
        };
        let clearance = closest_distance
            - footprint_support_radius(own.footprint, axis)
            - footprint_support_radius(neighbor.footprint, axis);
        let overlapping = tank::yaw_obb_contact(own.footprint, neighbor.footprint).is_some();
        let closing = delta.dot(relative_velocity) < 0.0;
        if !overlapping && (!closing || clearance >= VEHICLE_AVOID_CLEARANCE_M) {
            continue;
        }
        let urgency = if overlapping {
            1.0
        } else {
            ((VEHICLE_AVOID_CLEARANCE_M - clearance) / (VEHICLE_AVOID_CLEARANCE_M + 2.0))
                .clamp(0.0, 1.0)
        };
        if urgency <= 0.0 {
            continue;
        }

        let lateral = axis.dot(local_x);
        let avoid_steer = if lateral.abs() > 0.06 {
            -lateral.signum()
        } else {
            // An exactly head-on pair has no local left/right signal. Choose a shared WORLD-space
            // side from the pair axis, then project that side into each hull's steering frame. The
            // old ID-only local signs made opposite-facing tanks turn toward the same world side.
            // Coincident centers have no pair axis, so stable IDs choose opposite global sides.
            let world_side = if distance > 1.0e-4 {
                Vec2::new(-axis.y, axis.x)
            } else {
                let sign = if own.id < neighbor.id { -1.0 } else { 1.0 };
                let x_side = Vec2::X * sign;
                if x_side.dot(local_x).abs() > 0.06 {
                    x_side
                } else {
                    Vec2::Y * sign
                }
            };
            let local_turn = world_side.dot(local_x);
            if local_turn.abs() > 1.0e-5 {
                local_turn.signum()
            } else if own.id < neighbor.id {
                -1.0
            } else {
                1.0
            }
        };
        let ahead = axis.dot(forward);
        let replace = best.is_none_or(|(best_urgency, best_id, _, _)| {
            urgency > best_urgency + 1.0e-6
                || ((urgency - best_urgency).abs() <= 1.0e-6 && neighbor.id < best_id)
        });
        if replace {
            best = Some((urgency, neighbor.id, avoid_steer, ahead));
        }
    }

    let Some((urgency, _, avoid_steer, ahead)) = best else {
        return (drive, steer);
    };
    let steer_mix = (urgency * (0.35 + urgency * 0.65)).clamp(0.0, 1.0);
    let safe_steer = (steer * (1.0 - steer_mix) + avoid_steer * steer_mix).clamp(-1.0, 1.0);
    let moving_toward = desired_velocity.dot(forward * ahead) > 0.0 && ahead > -0.15;
    let safe_drive = if moving_toward {
        drive * (1.0 - urgency * 0.92)
    } else {
        drive
    };
    (safe_drive.clamp(-1.0, 1.0), safe_steer)
}

struct Slots {
    tiger: [usize; 3],               // hull, turret, gun
    tiger_glass: [Option<usize>; 3], // Schutzglas parts (hull visor / cupola blocks / TZF), see-through
    tiger_rtt: [Option<usize>; 3],   // RTT periscope screen meshes (atlas-bound)
    /// User-authored Tiger-relative props, parallel to `Game::tiger_dressing`.
    tiger_dressing: Vec<usize>,
    hatchlever: usize,      // the cupola hatch lever (E toggles the hatch)
    gunlever: usize,        // the breech lever (animated part, gun frame)
    breechcover: usize,     // the breech block cover (slides open with the lever)
    t34: Vec<[usize; 3]>,   // one T-34 hull/turret/gun triple per enemy slot
    su100: Vec<[usize; 3]>, // matching SU-100 triple; campaign waves can swap rigs per slot
    kv2: Vec<[usize; 3]>,
    isu152: Vec<[usize; 3]>,
    is2: Vec<[usize; 3]>,
    is3: Vec<[usize; 3]>,
    allies: Vec<[usize; 3]>, // two friendly Tigers in the Halbe finale
    hulk_t34: Vec<[usize; 3]>,
    hulk_su100: Vec<[usize; 3]>,
    hulk_kv2: Vec<[usize; 3]>,
    hulk_isu152: Vec<[usize; 3]>,
    hulk_is2: Vec<[usize; 3]>,
    hulk_is3: Vec<[usize; 3]>,
    /// ABANDONED TIGERS (the Last Tiger rule): up to 3 spare hulls scattered per act — reach one
    /// on foot after bailing out and the run continues. Empty on the arena (act 0).
    abandoned: Vec<[usize; 3]>,
    blast: [usize; N_BLAST], // pooled big fireballs (kill / turret-pop / cook-off)
    debris: [usize; N_DEBRIS], // pooled spark/debris chunks
    armor_scar: [usize; crate::armor_damage::MAX_ARMOR_SCARS],
    armor_patch: [usize; crate::armor_damage::MAX_ARMOR_SCARS],
    flame: Vec<usize>, // one persistent flickering flame plume per enemy wreck
    fire_flame_batch: [usize; FIRE_FLAME_BATCHES], // dense hot/yellow/orange/red flame cubes
    fire_smoke_batch: [usize; FIRE_SMOKE_BATCHES], // sparse dark-grey cubic soot
    bulb_housing: usize, // dark physical socket beneath the turret-roof fan
    bulb: usize,       // warm button/dome lens, lit only when the player is buttoned up
    turret_disc: usize, // articulated turret-basket floor; follows live traverse
    enigma: usize,     // physical machine mounted at the hull-right radio/bow-MG station
    binocular_prop: usize, // view-local physical field glasses during the lower/raise travel
    hatch: usize,      // cupola hatch lid (swings on a side hinge about engine-Y)
    // Animated interior parts (Phase 5): real baked meshes the engine drives.
    tpz_needle: usize,    // TPZ dial needle — spins 1:1 with turret-vs-hull bearing
    wheel1: usize,        // elevation handwheel — cranks with gun pitch
    wheel2: usize,        // commander's auxiliary traverse flywheel — follows turret yaw
    chamber_round: usize, // the chambered 8.8 round, visible while Breech::Loaded
    chamber_round_he: usize, // the SprGr twin (visibility swaps on the loaded nature)
    shell0: usize,        // first of SHELL_SLOTS.len() contiguous rack-shell instances
    snow: [usize; N_SNOW], // pooled near-miss snow/dust puffs (round-robin)
    // ── Crew-of-one interior workload FX (all pushed before the mg_flash/muzzle tail) ──
    breech: usize,    // main-gun breech block (heat rim glows amber right after firing)
    chambered: usize, // brass round seated in the breech (visible only when Loaded)
    ram_round: usize, // fresh round sliding home, Z driven by `ram`
    ready_rack: [usize; 3], // ready-rack rounds beside the breech (diegetic dressing)
    loose_shell: [usize; N_LOOSE], // dropped rounds rolling on the basket floor
    loose_shell_he: [usize; N_LOOSE], // yellow SprGr visual twins
    hammer: usize,    // first-person hammer (the track-repair ritual)
    toolbox: usize,   // the track-repair kit on the turret wall (hidden while carried)
    track_repair_shoes: [usize; N_REPAIR_SHOES], // loose run physically pulled over the wheels
    track_replacement_link: usize, // fresh link moved out of the kit and into the open break
    extinguisher: usize, // the wall-mounted extinguisher bottle (in hands while spraying)
    casing: [usize; N_CASING], // tumbling ejected casings (rigid body)
    foam_batch: [usize; N_FOAM_BATCHES], // instanced flying/stuck physical extinguisher grains
    annun: [usize; N_LAMP], // interior annunciator lamps (fire/breech/repair/station)
    breech_lamp: [usize; 3], // ON-BREECH state lamp: [green, orange, red] (one lit at a time)
    lan_crew: [usize; 5], // seated living body pool (permanent face identity slots)
    commander_crew: [usize; 5], // upright counterpart for each identity taking the cupola
    // One independently transformed textured mesh per anatomical segment and permanent identity.
    couch_dead: [[usize; crew_physics::CREW_BODY_PART_COUNT]; 5],
    // One reviewed 11-page skeleton pool per possible couch casualty. Bone pages share the same
    // physical segment transforms as flesh, but remain hidden until that flesh page is removed.
    couch_bones: [[usize; crew_physics::CREW_BODY_PART_COUNT]; COUCH_CREW_ROLES.len()],
    couch_gore: [usize; 4], // dark floor pool/fragments paired with each fallen body
    blood_cube_batch: [usize; N_BLOOD_BATCHES], // four dynamic instance batches, 256 grains each
    blood_stain: [usize; N_BLOOD_STAINS], // persistent floor/wall/breech dried marks
    hot_fragment_batch: [usize; N_HOT_FRAGMENT_BATCHES], // hot-orange/red cooling cube heads
    hot_fragment_tail_batch: [usize; N_HOT_FRAGMENT_BATCHES], // one speed streak per flying head
    micro_spark_batch: [usize; N_MICRO_SPARK_BATCHES], // visual-only 1–3 mm heads
    micro_spark_tail_batch: [usize; N_MICRO_SPARK_BATCHES], // hairline visual-only speed tails
    pen_flash: usize,       // interior-side molten entry flash
    pen_beam: usize,        // residual penetrator path, shown for only a few frames
    pen_burst: usize,       // filler/module fragmentation burst around the hole
    // ── Coax + hull MG34 FX (positioned before the muzzle/tracer/impact/smoke/e_fx tail so the
    // final-16 legacy FX layout — `mesh_count()-13` = smoke — is unchanged) ──
    mg_flash: usize, // single muzzle-flash mesh, placed at the live MG's port
    mg_tracer: [usize; N_MG_TRACER],
    mg_impact: [usize; N_MG_IMPACT],
    // ── ABSITZEN on-foot slots — pushed BEFORE the FX block so the FX block stays last and
    // `run_fire_demo`'s `mesh_count()-13` invariant holds untouched.
    pickup0: usize,                 // first supply-pickup mesh slot
    n_pickups: usize,               // count of contiguous pickup slots
    map_case: [usize; N_MAP_CASES], // physical intelligence folios at the generated search sites
    luger: usize,                   // first-person P08
    luger_mag: usize,               // physical magazine during reload
    luger_round: [usize; 3],        // truthful loose-round reload beat
    luger_casing: usize,            // pooled ejected 9 mm case
    luger_flash: [usize; LUGER_FLASH_FX],
    luger_impact: usize,
    panzerfaust: usize,
    panzerfaust_sight: usize,
    panzerfaust_projectile: usize,
    panzerfaust_flash: [usize; 2],
    panzerfaust_rack: [usize; PANZERFAUST_RACK],
    soldier0: usize, // first infantry mesh slot; N_SOLDIERS contiguous, 2 meshes each (body, rifle)
    inf_flash: [usize; INF_FX], // infantry return-fire muzzle boxes
    muzzle: usize,
    tracer: usize,
    impact: usize,
    smoke: usize,
    e_tracer: [usize; E_FX_POOL], // enemy return-fire tracer pool
    e_impact: [usize; E_FX_POOL],
    // ── Death instant-replay (kill-cam) FX — driven ONLY by render_replay, never in normal play ──
    r_shell: usize,             // the incoming shell streak (shooter → entry, slow-mo)
    r_muzzle: usize,            // shooter muzzle flash at t≈0
    r_flash: usize,             // penetration entry flash / lingering ember
    r_shards: [usize; N_SHARD], // spall/shrapnel fragments sprayed into the interior
    // X-RAY interior proxies (kill-cam only): the 5 crew + 12 modules as schematic boxes shown
    // through the screen-door-ghosted hull, the ones THIS shell killed flashing hot.
    r_crew: [usize; 5],
    r_mod: [usize; 12],
}

#[derive(Default)]
struct Fx {
    projectile_id: Option<u64>,
    muzzle_t: f32,
    tracer_active: bool,
    tracer_t: f32,
    tracer_dur: f32,
    tracer_from: Vec3,
    tracer_to: Vec3,
    tracer_dir: Vec3,
    impact_t: f32,
    impact_pos: Vec3,
    // Read-only projection of an already-resolved authoritative impact event. There is no pending
    // target/outcome freight in this presentation state.
    impact_kind: Outcome,
    smoke_t: f32, // muzzle smoke plume lifetime (longer, drifting cloud at the barrel)
    smoke_dur: f32,
}

/// One read-only external projectile presentation. Flight and terminal state live exclusively in
/// `Game::projectiles`; this pool only maps stable IDs to tracer/impact draw slots.
#[derive(Default, Clone)]
struct EnemyShot {
    projectile_id: Option<u64>,
    tracer_active: bool,
    tracer_t: f32,
    tracer_dur: f32,
    tracer_from: Vec3,
    tracer_to: Vec3,
    tracer_dir: Vec3,
    impact_t: f32,
    impact_pos: Vec3,
    impact_kind: Outcome,
}

/// A cannon streak is only a read-only view of a live stable-ID shell. `tracer_active` is retained
/// as presentation state, but it can never keep a draw alive after the authoritative owner has
/// resolved or retired. This guard is shared by the player and external pools so a terminal event
/// cannot leave the last submitted seven-metre streak frozen in world space.
fn authoritative_tracer_has_live_owner(projectile_id: Option<u64>, tracer_active: bool) -> bool {
    tracer_active && projectile_id.is_some()
}

/// A combat sound in flight to the player's ears — held in `Game::scheduled` and released by
/// `update` once its wavefront arrives (delay = source range / speed of sound). `buf`, when set,
/// is a SYNTHESIZED interleaved-stereo buffer (the parametric distant gun report) played instead of
/// the sampled `sfx` — the flash→bang path renders what that gun sounds like AFTER the air has
/// eaten its highs (acoustics::synth_gun_report). `volume` is the
/// already-range-attenuated amplitude handed to `Audio::play_at_volume`. Cheap and deterministic:
/// the queue is a plain Vec drained each frame, no allocation per sound beyond the push.
struct ScheduledSound {
    delay: f32, // seconds of travel time still remaining
    sfx: crate::audio::Sfx,
    volume: f32, // range-attenuated playback volume
    /// World origin retained until the wavefront arrives. The listener may have moved or turned in
    /// the intervening seconds, so pan and the direct acoustic ray are resolved at hear-time.
    source: Vec3,
    /// Synthesized stereo buffer (distant gun report etc.) — played INSTEAD of `sfx` when present.
    buf: Option<Vec<f32>>,
}

/// THE CLIMB RITUAL (embodied-interior Stage 1): mounting/dismounting the Tiger is a timed,
/// camera-scripted sequence up a ladder of perches — each Space is a committed ~0.5 s move (the
/// vulnerability window while enemies hunt you). Symmetric: 3 moves in, 3 moves out.
#[derive(Clone)]
struct Climb {
    active: bool,
    mounting: bool,  // true = ground → inside; false = inside → ground
    step: usize,     // index of the perch we're AT (or lerping FROM while `anim`)
    t: f32,          // 0..1 lerp progress within the current move
    anim: bool,      // true = a move is running (input locked); false = perched, awaiting Space
    cams: Vec<Vec3>, // camera world positions for each perch (eye-height baked in)
    end: ClimbEnd,   // what finishing the sequence does
}

#[derive(Clone, Copy)]
enum ClimbEnd {
    Afoot,
    IntoTank,
    IntoSpare(usize),
}

impl Default for Climb {
    fn default() -> Self {
        Climb {
            active: false,
            mounting: false,
            step: 0,
            t: 0.0,
            anim: false,
            cams: Vec::new(),
            end: ClimbEnd::Afoot,
        }
    }
}

/// Seconds per climb move — long enough to read as a physical heave, short enough to stay tense.
const CLIMB_STEP_S: f32 = 0.55;

/// The on-screen prompt for the current climb perch (Space advances; the last descent also walks off).
fn climb_prompt(mounting: bool, step: usize, n: usize) -> &'static str {
    if mounting {
        match step {
            0 => "CLIMB ONTO THE HULL [SPACE]",
            1 => "UP ONTO THE TURRET [SPACE]",
            _ => "DROP INTO THE HATCH [SPACE]",
        }
    } else {
        let _ = n;
        match step {
            0 => "PULL UP OUT OF THE CUPOLA [SPACE]",
            _ => "PULL OVER — ONTO THE CUPOLA [SPACE]",
        }
    }
}

/// Clamp an interior walk step to the TURRET FLOOR footprint, sliding around the breech box
/// (the one obstacle). Turret-local; only x/z move.
fn clamp_interior_walk(from: Vec3, to: Vec3) -> Vec3 {
    use crate::interior_rig as rig;
    let pad = 0.16; // body radius
    let mut p = to;
    p.x = p.x.clamp(rig::FLOOR_MIN.x + pad, rig::FLOOR_MAX.x - pad);
    p.z = p.z.clamp(rig::FLOOR_MIN.z + pad, rig::FLOOR_MAX.z - pad);
    let (bmin, bmax) = (rig::BREECH_MIN, rig::BREECH_MAX);
    let hit = |q: Vec3| {
        q.x > bmin.x - pad && q.x < bmax.x + pad && q.z > bmin.z - pad && q.z < bmax.z + pad
    };
    if hit(p) {
        // slide along whichever axis stays clear; a fully-blocked step stops
        let tryx = Vec3::new(p.x, p.y, from.z);
        let tryz = Vec3::new(from.x, p.y, p.z);
        p = if !hit(tryx) {
            tryx
        } else if !hit(tryz) {
            tryz
        } else {
            from
        };
    }
    p
}

