    /// Exact live ballistics-to-audio bridge output for the most recent player armor hit. Review
    /// tools copy it; gameplay never mutates sound behavior through this QA seam.
    pub fn debug_last_player_damage_sound(
        &self,
    ) -> Option<(
        crate::acoustics::ImpactParams,
        crate::acoustics::DamageSoundContext,
    )> {
        self.last_player_damage_sound
    }

    /// All physically present 8.8 cm rounds expressed in one penetration frame. This inventory is
    /// also the rendered inventory: untaken rack slots, a closed-breech chambered round, loose floor
    /// bodies, and the single round currently following the Loader's hands. Spent/taken slots are
    /// absent, so an empty rack cannot detonate.
    fn live_ammunition_in_frame(&self, frame: BloodFrame) -> Vec<LiveAmmoRound> {
        const AP_ID_BASE: u32 = 0x0000;
        const CHAMBER_ID: u32 = 0x1_0000;
        const LOOSE_ID_BASE: u32 = 0x2_0000;
        let round_radius = crate::procedural_ordnance::LIVE_MAX_DIAMETER_M * 0.5;
        let half_extents = Vec3::new(
            round_radius,
            round_radius,
            crate::procedural_ordnance::LIVE_LENGTH_M * 0.5,
        );
        let target_parent_inverse = blood_parent_model(&self.player, frame).inverse();
        let hm = self.player.hull_model();
        let tm = self.player.turret_model();
        let mut rounds = Vec::with_capacity(crate::interior_rig::SHELL_SLOTS.len() + N_LOOSE + 2);
        let mut push_round = |stable_id: u32, world_model: Mat4, high_explosive: bool| {
            let local_model = target_parent_inverse * world_model;
            let (_, rotation, center) = local_model.to_scale_rotation_translation();
            let filler_g = if high_explosive {
                crate::ballistics::SPRGR_88.filler_g
            } else {
                crate::ballistics::PZGR_39.filler_g
            };
            rounds.push(LiveAmmoRound {
                stable_id,
                center,
                rotation: rotation.normalize(),
                half_extents,
                explosive_energy_j: filler_g.max(0.0) * 4_184.0,
            });
        };

        for (index, (slot_frame, position, quaternion)) in
            crate::interior_rig::SHELL_SLOTS.iter().enumerate()
        {
            if self.slot_taken[index] {
                continue;
            }
            let parent = if *slot_frame == crate::interior_rig::Frame::Hull {
                hm
            } else {
                tm
            };
            let rotation =
                Quat::from_xyzw(quaternion[0], quaternion[1], quaternion[2], quaternion[3])
                    .normalize();
            push_round(
                AP_ID_BASE + index as u32,
                parent * Mat4::from_rotation_translation(rotation, *position),
                self.slot_nature_he.get(index).copied().unwrap_or(false),
            );
        }

        if matches!(self.breech, Breech::Loaded) {
            push_round(
                CHAMBER_ID,
                tm * Mat4::from_translation(crate::interior_rig::ROUND_SEAT),
                self.he_loaded,
            );
        }

        for (index, shell) in self.loose.iter().enumerate() {
            if !shell.active {
                continue;
            }
            push_round(
                LOOSE_ID_BASE + index as u32,
                tm * Mat4::from_translation(shell.pos)
                    * Mat4::from_rotation_y(shell.axis)
                    * Mat4::from_rotation_z(shell.spin),
                shell.nature_he,
            );
        }

        if let Some(carried) = self.carry_mesh {
            let align = (self.ram / 0.16).clamp(0.0, 1.0);
            let enter = ((self.ram - 0.10) / 0.90).clamp(0.0, 1.0);
            let ready = tm.transform_point3(crate::interior_rig::ROUND_READY);
            let seat = tm.transform_point3(crate::interior_rig::ROUND_SEAT);
            let position = self.carry_pos.lerp(ready, align).lerp(seat, enter);
            let nose = self
                .carry_dir
                .lerp(self.player.turret_forward().normalize_or_zero(), align)
                .normalize_or_zero();
            let rotation = if nose.length_squared() > 0.5 {
                Quat::from_rotation_arc(Vec3::Z, nose)
            } else {
                Quat::IDENTITY
            };
            let (stable_id, high_explosive) = match carried {
                CarriedMesh::RackShell(index) => (
                    AP_ID_BASE + index as u32,
                    self.slot_nature_he.get(index).copied().unwrap_or(false),
                ),
                CarriedMesh::LooseShell(index) => {
                    (LOOSE_ID_BASE + index as u32, self.loose[index].nature_he)
                }
            };
            push_round(
                stable_id,
                Mat4::from_rotation_translation(rotation, position),
                high_explosive,
            );
        }

        rounds.sort_by_key(|round| round.stable_id);
        rounds
    }

    fn internal_ammo_blast(
        &self,
        frame: BloodFrame,
        contacts: &[FragmentDamageContact],
        preferred_world: Option<Vec3>,
        seed: u32,
    ) -> Option<InternalAmmoBlast> {
        let rounds = self.live_ammunition_in_frame(frame);
        if rounds.is_empty() {
            return None;
        }
        let preferred_local = contacts
            .iter()
            .find_map(|contact| {
                (contact.target == FragmentDamageTarget::Module(ModuleKind::AmmoRack))
                    .then_some(contact.internal_blast_origin_local)
                    .flatten()
            })
            .or_else(|| {
                preferred_world.map(|world| {
                    blood_parent_model(&self.player, frame)
                        .inverse()
                        .transform_point3(world)
                })
            });
        let source = preferred_local.map_or(rounds[0], |preferred| {
            rounds
                .iter()
                .copied()
                .min_by(|a, b| {
                    a.center
                        .distance_squared(preferred)
                        .total_cmp(&b.center.distance_squared(preferred))
                        .then_with(|| a.stable_id.cmp(&b.stable_id))
                })
                .unwrap_or(rounds[0])
        });
        let explosive_energy_j = rounds
            .iter()
            .map(|round| round.explosive_energy_j)
            .sum::<f32>();
        Some(InternalAmmoBlast {
            origin_world: blood_parent_model(&self.player, frame).transform_point3(source.center),
            explosive_energy_j,
            seed,
        })
    }

    /// Transition every represented live cartridge into the detonation. The initiating blast has
    /// already snapshotted the typed inventory energy and source position before this is called;
    /// leaving rack/chamber/loose/hand meshes behind would duplicate that consumed mass in replays.
    fn consume_live_ammunition_for_detonation(&mut self) {
        self.slot_taken.fill(true);
        self.breech = Breech::Empty;
        self.lever_open = 1.0;
        self.ram = 0.0;
        self.carry_mesh = None;
        self.grab = false;
        self.loose.fill(LooseShell::default());
    }

    /// Deterministic, bounded cube-to-steel contacts from the latest FX step. The aggregate count
    /// reports the full collision storm even when the spatial sample reaches its audio-safe cap.
    pub fn hot_fragment_collisions(&self) -> &[HotFragmentCollision] {
        &self.hot_fragment_collisions
    }

    pub fn hot_fragment_collision_count(&self) -> usize {
        self.hot_fragment_collision_count
    }

    /// Deterministic visual-only penetration used by the `penfx` comparison. It resolves a real
    /// BR-471 against the Tiger's real turret-side plate, then stages the same physical bodies a live
    /// penetration would create without mutating crew/modules in this comparison helper.
    pub fn debug_spawn_penetration_fx(&mut self) {
        let (turret_min, _) =
            rig_armor_bounds(crate::ballistics::ArmorScheme::TigerI, ArmorPart::Turret)
                .expect("Tiger turret bounds");
        let entry_local = Vec3::new(turret_min.x, 1.77, 0.10);
        let axis_local = Vec3::new(0.96, 0.04, 0.24).normalize();
        let plate =
            crate::ballistics::ArmorScheme::TigerI.plate(crate::ballistics::Facing::TurretSide);
        let ev =
            crate::ballistics::resolve(&crate::ballistics::BR_471, 50.0, plate, 2.0, 0x5045_4E46);
        debug_assert!(matches!(
            ev.terminal,
            crate::ballistics::Terminal::Penetration
        ));
        let fragments = generate_penetration_fragments(
            0x5045_4E46,
            BloodFrame::Turret,
            entry_local,
            axis_local,
            ev,
            0x5045_4E46,
        );
        self.stage_penetration_fragments(&fragments);
    }

    /// Run the exact damage solver read-only for one deterministic Loader witness seed. The film
    /// harness uses this to select the physical fragment realization that harms the fewest crew,
    /// includes the Loader, and does not strike live ammunition. No trajectory, target or outcome
    /// is edited.
    fn probe_loader_side_penetration_seed(
        &self,
        loader_peer: u32,
        shell: &'static crate::ballistics::ShellSpec,
        penetration_id: u64,
        seed: u32,
    ) -> Option<(usize, bool, bool)> {
        let frame = BloodFrame::Turret;
        let turret = self.player.turret_model();
        let (_, loader_segments) =
            crew_pose_segments_in_frame(&self.player, crate::lan::LanRole::Loader, frame);
        let loader_local = loader_segments[crew_physics::CrewBodyPart::Head.index()].pos;
        let (turret_min, _) =
            rig_armor_bounds(crate::ballistics::ArmorScheme::TigerI, ArmorPart::Turret)?;
        let entry = Vec3::new(turret_min.x, loader_local.y, loader_local.z);
        let axis = (loader_local - entry).normalize_or_zero();
        let plate =
            crate::ballistics::ArmorScheme::TigerI.plate(crate::ballistics::Facing::TurretSide);
        let event = crate::ballistics::resolve(shell, 50.0, plate, 0.0, seed);
        if !matches!(event.terminal, crate::ballistics::Terminal::Penetration) {
            return None;
        }
        let fragments =
            generate_penetration_fragments(penetration_id, frame, entry, axis, event, seed);
        let mut bodies = couch_crew_bodies(
            self.couch_crew_frame,
            &self.couch_kia_peers,
            &self.couch_crew_identities,
        );
        for body in &mut bodies {
            let (scale, segments) =
                crew_pose_segments_in_frame(&self.player, body.casualty.role, frame);
            body.pos = crew_physics::center_of_mass(&segments);
            body.hit_volumes = crew_hit_volumes_from_segments(&segments, scale);
        }
        let parent_inverse = turret.inverse();
        let hull = self.player.hull_model();
        let module_centers: Vec<(ModuleKind, Vec3)> = self
            .modules
            .iter()
            .map(|module| {
                (
                    module.kind,
                    parent_inverse.transform_point3(hull.transform_point3(module.kind.station())),
                )
            })
            .collect();
        let ammunition = self.live_ammunition_in_frame(frame);
        let mut modules = self.modules.clone();
        let (result, hits, _) = resolve_fragment_damage(
            &fragments,
            None,
            &bodies,
            &module_centers,
            &ammunition,
            &mut modules,
        );
        let loader_hit = hits.iter().any(|casualty| {
            casualty.peer_id == loader_peer && casualty.role == crate::lan::LanRole::Loader
        });
        Some((hits.len(), loader_hit, result.ammo))
    }

    /// Cinematic proof shot: a real shell enters the turret from physical right and the normal
    /// armor/spall resolver crosses the Loader's anatomical volume. Success requires a newly written
    /// Loader casualty plus its articulated corpse. The live resolver can only write that ledger
    /// entry after a lethal swept contact with one of the Loader's eleven pose-matched OBBs; there is
    /// no fabricated KIA or repeated penetration hidden between takes.
    fn debug_loader_side_penetration_round(
        &mut self,
        shell: &'static crate::ballistics::ShellSpec,
        penetration_id: u64,
        base_seed: u32,
    ) -> bool {
        let Some(loader_peer) = self.couch_role_occupant(crate::lan::LanRole::Loader) else {
            return false;
        };
        let bodies = couch_crew_bodies(
            self.couch_crew_frame,
            &self.couch_kia_peers,
            &self.couch_crew_identities,
        );
        if bodies.is_empty() {
            return false;
        }
        let mut selected: Option<(u32, usize)> = None;
        for index in 0..256u32 {
            let candidate = base_seed.wrapping_add(index.wrapping_mul(0x9E37_79B9));
            let Some((hit_count, loader_hit, ammo_hit)) = self.probe_loader_side_penetration_seed(
                loader_peer,
                shell,
                penetration_id,
                candidate,
            ) else {
                continue;
            };
            if !loader_hit || ammo_hit {
                continue;
            }
            if selected.is_none_or(|(_, old_count)| hit_count < old_count) {
                selected = Some((candidate, hit_count));
            }
            if hit_count == 1 {
                break;
            }
        }
        let (seed, predicted_hits) = selected.unwrap_or((base_seed, usize::MAX));
        println!(
            "[terror-video] selected physical {} Loader witness seed {seed:#010x} ({predicted_hits} predicted crew hit(s))",
            shell.name,
        );
        let turret = self.player.turret_model();
        // Aim the QA shell through the exact seated head OBB used by live fragment collision. The
        // high line stays clear of the side-wall ammunition bins, so this witness exercises severe
        // anatomical casualties without turning every take into a four-man rack cook-off.
        // The previous choreography retained the centre of the obsolete one-sphere crew proxy;
        // after anatomical collision landed, that point correctly sat in empty space between the
        // Loader's bent segments. This changes only the deterministic witness shot, never the live
        // volume sizes, fragment cone, armor solution, energy or casualty policy.
        let (_, loader_segments) = crew_pose_segments_in_frame(
            &self.player,
            crate::lan::LanRole::Loader,
            BloodFrame::Turret,
        );
        let loader_local = loader_segments[crew_physics::CrewBodyPart::Head.index()].pos;
        let (turret_min, _) =
            rig_armor_bounds(crate::ballistics::ArmorScheme::TigerI, ArmorPart::Turret)
                .expect("Tiger turret bounds");
        // Exact right-side armor coordinate, aimed through the loader's rendered head. No entry
        // clamping or centre-pull is involved.
        let entry_turret = Vec3::new(turret_min.x, loader_local.y, loader_local.z);
        let entry_world = turret.transform_point3(entry_turret);
        let axis_local = (loader_local - entry_turret).normalize_or_zero();
        let shell_dir_world = turret.transform_vector3(axis_local).normalize_or_zero();
        let shooter = entry_world - shell_dir_world * 50.0;
        let facing = crate::ballistics::Facing::TurretSide;
        let plate = crate::ballistics::ArmorScheme::TigerI.plate(facing);
        let event = crate::ballistics::resolve(shell, 50.0, plate, 0.0, seed);
        if !matches!(event.terminal, crate::ballistics::Terminal::Penetration) {
            return false;
        }

        self.hatch_open = false;
        self.commander_outside = false;
        self.god = false;
        self.armor_scars.record(facing, entry_turret, &event);
        self.stat_hits_on_player = self.stat_hits_on_player.saturating_add(1);
        self.stat_pens_on_player = self.stat_pens_on_player.saturating_add(1);
        self.hit_camera_kick = (self.hit_camera_kick + shell_dir_world * 0.46 + Vec3::Y * 0.035)
            .clamp_length_max(0.72);
        self.concussion_t = 0.0;
        self.concussion_dur = 7.5;
        self.concussion_profile = crate::acoustics::ConcussionProfile {
            floor_gain: 0.065,
            hold_s: 0.34,
            recovery_s: 7.16,
            tinnitus_gain: 1.0,
        };
        self.schedule_sound_from(
            crate::audio::Sfx::PenetrationHit,
            entry_world,
            VOL_PENETRATION,
        );
        let casualty_start = self.couch_casualties.len();
        self.resolve_player_penetration(
            Arc::Side,
            shooter,
            entry_world,
            shell_dir_world,
            ArmorPart::Turret,
            entry_turret,
            penetration_id,
            seed,
            event,
        );
        let expected = CouchCrewCasualty {
            peer_id: loader_peer,
            identity: crate::lan::LanRole::Loader,
            role: crate::lan::LanRole::Loader,
        };
        let new_casualties = &self.couch_casualties[casualty_start..];
        new_casualties.contains(&expected)
            && self.player.alive
            && self.death_cause.is_none()
            && self.module_ok(ModuleKind::AmmoRack)
            && self
                .couch_ragdolls
                .iter()
                .any(|ragdoll| ragdoll.casualty == expected)
    }

    /// Catastrophic 122 mm anatomical-breakup witness.
    pub fn debug_loader_side_penetration(&mut self) -> bool {
        self.debug_loader_side_penetration_round(
            &crate::ballistics::BR_471,
            0x10AD_E421,
            0x10AD_E421,
        )
    }

    /// Common T-34 76 mm witness: the same live solver, with less filler so enough connected
