    pub fn clear_last_couch_casualty(&mut self) {
        self.couch_last_casualty = None;
    }

    /// Headless verification hook: incapacitate the living couch peer at its current physical post.
    /// This bypasses penetration RNG but uses the same stable-ID casualty ledger and terminal
    /// all-crew-lost policy as a real spall hit.
    pub fn debug_couch_kia(&mut self, peer_id: u32) -> bool {
        let Some(casualty) = couch_crew_bodies(
            self.couch_crew_frame,
            &self.couch_kia_peers,
            &self.couch_crew_identities,
        )
        .into_iter()
        .find(|body| body.casualty.peer_id == peer_id)
        .map(|body| body.casualty) else {
            return false;
        };
        self.crew_ko_t = CREW_KO_DUR;
        self.crew_ko_world_dir = self
            .player
            .hull_model()
            .transform_vector3(Vec3::new(0.72, 0.18, 0.66))
            .normalize_or_zero();
        let casualty_start = self.couch_casualties.len();
        let crew_wiped = record_couch_casualties(
            self.couch_crew_frame,
            &self.couch_crew_identities,
            &mut self.couch_kia_peers,
            &mut self.couch_casualties,
            &mut self.couch_last_casualty,
            &[casualty],
        );
        if self.couch_casualties.len() > casualty_start {
            let axis = self.crew_ko_world_dir;
            let seed = 0xB100_D000 ^ peer_id.wrapping_mul(7919);
            self.spawn_couch_ragdoll(casualty, axis, 1.20, seed ^ 0x2A66_D011);
            self.spawn_cubic_blood(
                casualty,
                None,
                axis,
                Vec3::ZERO,
                1.20,
                1.0,
                seed,
                casualty_start,
                blood_body_count(1.20),
            );
        }
        if crew_wiped {
            self.player.alive = false;
            self.death_cause = Some(DeathCause::CrewLost);
            self.recompute_hp();
        }
        true
    }

    /// Resolve a single physically located ammunition blast against every living couch crewman.
    /// Exact incoming fragment contacts keep their anatomical part/momentum; all other parts still
    /// receive distance-based pressure work from the same source. No camera vector or per-victim
    /// invented explosion is admitted here.
    fn kill_all_couch_crew_from_blast(
        &mut self,
        blast: InternalAmmoBlast,
        contact_frame: BloodFrame,
        contacts: &[FragmentDamageContact],
    ) {
        if !self.couch_crew_active {
            return;
        }
        let contact_parent = blood_parent_model(&self.player, contact_frame);
        let blast_origin_local = contact_parent
            .inverse()
            .transform_point3(blast.origin_world);
        let mut bodies = couch_crew_bodies(
            self.couch_crew_frame,
            &self.couch_kia_peers,
            &self.couch_crew_identities,
        );
        for body in &mut bodies {
            let (scale, segments) =
                crew_pose_segments_in_frame(&self.player, body.casualty.role, contact_frame);
            body.pos = crew_physics::center_of_mass(&segments);
            body.hit_volumes = crew_hit_volumes_from_segments(&segments, scale);
        }
        let hits: Vec<CouchCrewCasualty> = bodies.iter().map(|body| body.casualty).collect();
        if !hits.is_empty() {
            self.crew_ko_t = CREW_KO_DUR;
            let crew_center = bodies
                .iter()
                .map(|body| contact_parent.transform_point3(body.pos))
                .fold(Vec3::ZERO, |sum, point| sum + point)
                / bodies.len() as f32;
            self.crew_ko_world_dir = (crew_center - blast.origin_world).normalize_or_zero();
        }

        let mut plans = Vec::with_capacity(bodies.len());
        for body in &bodies {
            let mut energy_by_part = [0.0f32; crew_physics::CREW_BODY_PART_COUNT];
            let mut strongest_by_part: [Option<FragmentDamageContact>;
                crew_physics::CREW_BODY_PART_COUNT] = [None; crew_physics::CREW_BODY_PART_COUNT];
            for &contact in contacts {
                if contact.target != FragmentDamageTarget::CouchCrew(body.casualty) {
                    continue;
                }
                let Some(part) = contact.body_part else {
                    continue;
                };
                let index = part.index();
                energy_by_part[index] =
                    (energy_by_part[index] + contact.energy_j.max(0.0)).min(10_000_000.0);
                if strongest_by_part[index].is_none_or(|old| {
                    contact.energy_j > old.energy_j
                        || (contact.energy_j == old.energy_j
                            && contact.fragment_id < old.fragment_id)
                }) {
                    strongest_by_part[index] = Some(contact);
                }
            }

            let mut events = Vec::with_capacity(crew_physics::CREW_BODY_PART_COUNT);
            for part in crew_physics::CrewBodyPart::ALL {
                let index = part.index();
                let volume = body.hit_volumes[index];
                let result = crew_damage::resolve_crew_damage(crew_damage::CrewDamageInput {
                    part,
                    fragment_energy_j: energy_by_part[index],
                    explosive_energy_j: blast.explosive_energy_j,
                    blast_distance_m: volume.center.distance(blast_origin_local),
                });
                if result.outcome == crew_damage::CrewTissueOutcome::None {
                    continue;
                }
                let strongest_contact = strongest_by_part[index];
                let wound_world = strongest_contact.map_or_else(
                    || contact_parent.transform_point3(volume.center),
                    |contact| contact_parent.transform_point3(contact.local_point),
                );
                let mut ejection_world = strongest_contact.map_or_else(
                    || wound_world - blast.origin_world,
                    |contact| contact_parent.transform_vector3(contact.local_velocity),
                );
                if ejection_world.length_squared() < 0.2 {
                    ejection_world = wound_world - blast.origin_world;
                }
                events.push(CatastrophicCrewPartEvent {
                    result,
                    wound_world,
                    ejection_world,
                    strongest_contact,
                });
            }

            let primary = events.iter().copied().max_by(|a, b| {
                a.result
                    .total_work_j
                    .total_cmp(&b.result.total_work_j)
                    .then_with(|| b.result.part.index().cmp(&a.result.part.index()))
            });
            let (impact_part, point_world, velocity_world, fragment_energy_j, proximity) = primary
                .map_or_else(
                    || {
                        let nearest = crew_physics::CrewBodyPart::ALL
                            .into_iter()
                            .min_by(|a, b| {
                                body.hit_volumes[a.index()]
                                    .center
                                    .distance_squared(blast_origin_local)
                                    .total_cmp(
                                        &body.hit_volumes[b.index()]
                                            .center
                                            .distance_squared(blast_origin_local),
                                    )
                            })
                            .unwrap_or(crew_physics::CrewBodyPart::Torso);
                        let point = contact_parent
                            .transform_point3(body.hit_volumes[nearest.index()].center);
                        (
                            nearest,
                            point,
                            Vec3::ZERO,
                            0.0,
                            point.distance(blast.origin_world),
                        )
                    },
                    |event| {
                        (
                            event.result.part,
                            event.wound_world,
                            event
                                .strongest_contact
                                .map_or(Vec3::ZERO, |_| event.ejection_world),
                            event.result.fragment_work_j,
                            event.wound_world.distance(blast.origin_world),
                        )
                    },
                );
            plans.push(CatastrophicCrewPlan {
                casualty: body.casualty,
                impact: CrewRagdollImpact {
                    hit_part: impact_part,
                    point_world,
                    velocity_world,
                    energy_j: fragment_energy_j,
                    blast_origin_world: blast.origin_world,
                    explosive_energy_j: blast.explosive_energy_j,
                    behind_armor: 1.65,
                    blast_proximity_m: proximity,
                },
                events,
            });
        }

        let casualty_start = self.couch_casualties.len();
        let _ = record_couch_casualties(
            self.couch_crew_frame,
            &self.couch_crew_identities,
            &mut self.couch_kia_peers,
            &mut self.couch_casualties,
            &mut self.couch_last_casualty,
            &hits,
        );
        let newly_recorded = self.couch_casualties.len().saturating_sub(casualty_start);
        if newly_recorded > 0 {
            let casualty_budget = (N_BLOOD_CUBES / newly_recorded).max(16);
            for (plan_index, plan) in plans.into_iter().take(newly_recorded).enumerate() {
                let casualty_seed = blast.seed
                    ^ plan.casualty.peer_id.wrapping_mul(6151)
                    ^ self.kill_tick.wrapping_add(plan_index as u32);
                let source_to_ragdoll =
                    blood_parent_model(&self.player, blood_frame_for_role(plan.casualty.role))
                        .inverse()
                        * blood_parent_model(&self.player, contact_frame);
                self.spawn_couch_ragdoll_impact(
                    plan.casualty,
                    plan.impact,
                    casualty_seed ^ 0x2A66_D011,
                );
                if let Some(ragdoll) = self
                    .couch_ragdolls
                    .iter_mut()
                    .find(|ragdoll| ragdoll.casualty == plan.casualty)
                {
                    let mut fragment_impulses = [Vec3::ZERO; crew_physics::CREW_BODY_PART_COUNT];
                    fragment_impulses[plan.impact.hit_part.index()] += ragdoll.fragment_impulse_ns;
                    for event in &plan.events {
                        if event.result.part != plan.impact.hit_part {
                            if let Some(contact) = event.strongest_contact {
                                fragment_impulses[event.result.part.index()] +=
                                    crew_physics::apply_fragment_impulse_to_part(
                                        &mut ragdoll.segments,
                                        event.result.part,
                                        source_to_ragdoll.transform_point3(contact.local_point),
                                        source_to_ragdoll.transform_vector3(contact.local_velocity),
                                        event.result.fragment_work_j,
                                        ragdoll.scale,
                                    );
                            }
                        }
                    }
                    let pulverized: [bool; crew_physics::CREW_BODY_PART_COUNT] =
                        std::array::from_fn(|index| {
                            plan.events.iter().any(|event| {
                                event.result.part.index() == index && event.result.hide_mesh_part
                            })
                        });
                    crew_physics::couple_pulverized_fragment_impulses(
                        &mut ragdoll.segments,
                        &fragment_impulses,
                        &pulverized,
                    );
                    for event in &plan.events {
                        let segment = &mut ragdoll.segments[event.result.part.index()];
                        segment.detached |= event.result.detach_joint;
                    }
                    apply_crew_pulverization(ragdoll, &pulverized);
                }

                let requests: Vec<usize> = plan
                    .events
                    .iter()
                    .map(|event| event.result.blood_cube_count)
                    .collect();
                let allocations = allocate_blood_cube_budget(&requests, casualty_budget);
                for (event_index, (event, count)) in
                    plan.events.iter().zip(allocations.into_iter()).enumerate()
                {
                    if count == 0 {
                        continue;
                    }
                    let ejection_strength = match event.result.outcome {
                        crew_damage::CrewTissueOutcome::None => 0.55,
                        crew_damage::CrewTissueOutcome::Injury => 1.0,
                        crew_damage::CrewTissueOutcome::Detachment => 1.72,
                        crew_damage::CrewTissueOutcome::Pulverized => 2.65,
                    };
                    self.spawn_cubic_blood(
                        plan.casualty,
                        Some(event.wound_world),
                        event.ejection_world,
                        self.couch_ragdolls
                            .iter()
                            .find(|ragdoll| ragdoll.casualty == plan.casualty)
                            .map(|ragdoll| {
                                blood_parent_model(&self.player, ragdoll.frame).transform_vector3(
                                    ragdoll.segments[event.result.part.index()].vel,
                                )
                            })
                            .unwrap_or(Vec3::ZERO),
                        1.65,
                        ejection_strength,
                        casualty_seed ^ (event_index as u32).wrapping_mul(0x9E37_79B9),
                        casualty_start + plan_index,
                        count,
                    );
                }
            }
        }
    }

    /// Put this process's camera/body at its claimed LAN station without a solo clamber delay. The
    /// host simulation still receives all five stations concurrently through `TankInput::coop`.
    pub fn set_lan_role(&mut self, role: crate::lan::LanRole) {
        self.lan_local_role = Some(role);
        let station = match role {
            crate::lan::LanRole::Commander => Station::Commander,
            crate::lan::LanRole::Driver => Station::Driver,
            crate::lan::LanRole::Gunner => Station::Gunner,
            crate::lan::LanRole::Loader => Station::Loader,
            crate::lan::LanRole::Radio => Station::Radioman,
        };
        if self.station != station {
            self.station = station;
            self.switch_from = station;
            self.switch_t = 0.0;
            self.switch_dur = 0.0;
            self.grab = false;
            self.carry_mesh = None;
        }
    }

    /// The gunner's ADS view composites the live optic circle INSIDE the turret interior
    /// (crush mask 4) instead of floating it in black. Off during the seat-switch scramble
    /// (the camera is mid-lerp between stations) and in the dev chase cam.
    pub fn optic_composite_active(&self) -> bool {
        matches!(self.mode, Mode::Tank)
            && matches!(self.station, Station::Gunner)
            && self.switch_t <= 0.0
            && !self.chase_cam
    }

    /// EYEPIECE COMPOSITE interior camera: the gunner's head just behind the TZF eyepiece
    /// (turret-local anchor (0.536, 1.99, 0.81) is the authored sight), looking down the
    /// turret's forward axis so the optic circle sits dead-center; wide field so the breech,
    /// wall and roof frame it. Returns (eye, forward, fov_y).
    pub fn gunner_interior_camera(&self) -> (Vec3, Vec3, f32) {
        let tm = self.player.turret_model();
        let eye = tm.transform_point3(Vec3::new(0.536, 1.955, 0.34));
        let sight = tm.transform_point3(Vec3::new(0.536, 1.975, 0.81));
        (eye, sight - eye, 66f32.to_radians())
    }

    /// Apply the current main-gun and armor-hit camera impulses to an already-authored base pose.
    /// This does not advance any timers, so the keyboard view, all controller split views, and a
    /// deterministic film camera can sample the exact same physical instant independently.
    pub fn apply_cinematic_camera_impulses(&self, r: &mut Renderer) {
        if let Some(age) = self.player.shot_age() {
            let optic = r.optic_mask > 0.5;
            let exposed = !optic && r.interior_light < 0.5;
            let sample = main_gun_camera_sample(age, optic, exposed);
            let forward = r.camera.forward();
            r.camera.pos += -forward * sample.back + Vec3::Y * sample.up;
            r.camera.yaw += sample.yaw;
            r.camera.pitch += sample.pitch;
        }
        if self.hit_camera_kick.length_squared() > 1e-6 {
            let camera_right = r.camera.right();
            r.camera.pos += self.hit_camera_kick;
            r.camera.yaw += self.hit_camera_kick.dot(camera_right) * 0.055;
            r.camera.pitch -= self.hit_camera_kick.length() * 0.035;
        }
    }

    /// Apply the view-local cabin treatment immediately before a crew viewport renders. Couch
    /// cameras share one Renderer but not one physical viewpoint: the gunner's exterior optic must
    /// stay clean while his eyepiece-composite surround, the driver, loader and buttoned commander
    /// retain their physical cabin geometry, gun haze and suspended dust.
    pub fn configure_crew_render_view(
        &self,
        role: crate::lan::LanRole,
        optic_view: bool,
        r: &mut Renderer,
    ) {
        let commander_exposed = self.hatch_open && self.commander_outside;
        let inside = matches!(self.mode, Mode::Tank)
            && crew_render_inside(role, optic_view, commander_exposed, self.driver_hatch);
        let interior = if inside { 1.0 } else { 0.0 };
        r.interior_light = interior;
        r.rt_mix = 1.0 - interior;
        r.interior_haze = if inside {
            0.06 + self.interior_haze * 0.88
        } else {
            0.0
        };
        r.set_interior_atmosphere_enabled(inside);
        // The gunner's pass-A sight snapshot is a clean exterior image; pass B applies the shared
        // casualty spray once over the eyepiece surround/final frame. Every other surviving couch
        // camera gets the same event, projected into its own screen basis.
        r.crew_ko = if optic_view {
            0.0
        } else {
            crew_ko_progress(self.crew_ko_t, self.force_crew_ko)
        };
        r.crew_ko_dir = self
            .force_crew_ko_dir
            .unwrap_or_else(|| project_screen_dir(self.crew_ko_world_dir, &r.camera));
    }

    /// COUCH-COOP: camera pose for a splitscreen viewport showing another crewman's station this
    /// frame. Pure function of the tank pose (the gun IS the gunner's eye, the visor is the
    /// driver's), so extra views render after `update` without touching the local player's
    /// camera bookkeeping. Returns (eye, forward, fov_y, optic_mask, reticle).
    pub fn coop_view_camera(&self, role: crate::lan::LanRole) -> (Vec3, Vec3, f32, f32, bool) {
        match role {
            crate::lan::LanRole::Gunner => {
                let (_mpos, mdir) = self.player.muzzle();
                let fov = [25f32, 12.0, 6.0][self.sights_mag.min(2) as usize].to_radians();
                (
                    self.player.gunsight(),
                    mdir,
                    fov,
                    1.0,
                    self.module_ok(ModuleKind::GunnerSight),
                )
            }
            crate::lan::LanRole::Driver => {
                // The couch driver must actually SEE to drive: eye up near the visor line and the
                // camera aimed at the forward slit aperture (hull-local (+0.547, 1.738, 2.386)), so the
                // daylight band sits dead-center in the letterbox instead of being cropped away
                // (the solo seat eye looks level and shows mostly glacis interior).
                let hm = self.player.hull_model();
                let eye = hm.transform_point3(Vec3::new(0.535, 1.68, 1.82));
                let slit = hm.transform_point3(Vec3::new(0.547, 1.738, 2.386));
                (eye, slit - eye, 48f32.to_radians(), 2.0, false)
            }
            crate::lan::LanRole::Radio => (
                self.station_eye(Station::Radioman),
                self.player.forward(),
                54f32.to_radians(),
                2.0,
                false,
            ),
            crate::lan::LanRole::Loader => {
                // Dedicated fourth couch view: stand at the loader's authored side of the basket
                // and face the breech. The network-stable service control remains authoritative;
                // this fixed protected camera lets that player read the block/casing/round state.
                let tm = self.player.turret_model();
                let eye = tm.transform_point3(Vec3::new(
                    -0.85,
                    crate::interior_rig::FLOOR_STAND_Y + 1.29,
                    0.15,
                ));
                let breech =
                    (crate::interior_rig::BREECH_MIN + crate::interior_rig::BREECH_MAX) * 0.5;
                let target = tm.transform_point3(breech);
                (eye, target - eye, 62f32.to_radians(), 0.0, false)
            }
            crate::lan::LanRole::Commander => {
                let base = self.player.turret_forward();
                let yaw = base.x.atan2(-base.z) + self.couch_commander_yaw;
                let pitch = (self.couch_commander_pitch - 0.10).clamp(-1.2, 1.2);
                let cp = pitch.cos();
                let forward = Vec3::new(yaw.sin() * cp, pitch.sin(), -yaw.cos() * cp);
                let binoculars_requested = self.couch_crew_active
                    && self
                        .couch_crew_frame
                        .input(crate::lan::LanRole::Commander)
                        .flag(crate::lan::F_BINOCULARS);
                let binoculars =
                    binoculars_requested && binocular_optics_ready(self.couch_binocular_raise);
                (
                    self.station_eye(Station::Commander),
                    forward,
                    if binoculars {
                        BINOCULAR_FOV_DEG.to_radians()
                    } else {
                        64f32.to_radians()
                    },
                    if binoculars { 3.0 } else { 0.0 },
                    binoculars,
                )
            }
        }
    }

    /// Compact host-authoritative state for LAN reconciliation. Transient particles remain local;
    /// the machine, ammunition, crew/modules and every active enemy are authoritative.
    pub fn net_snapshot(&self) -> crate::lan::WorldSnapshot {
        let tank = |t: &Tank| crate::lan::NetTankState {
            pos: t.pos.to_array(),
            heading: t.heading,
            speed: t.speed,
            turret_yaw: t.turret_yaw,
            gun_pitch: t.gun_pitch,
            reload: t.reload,
            hp: t.hp,
            alive: t.alive,
        };
        let module_mask = self
            .modules
            .iter()
            .enumerate()
            .fold(0u16, |mask, (i, module)| {
                mask | ((module.functional as u16) << i)
            });
        let crew_mask = self
            .crew
            .iter()
            .enumerate()
            .fold(0u8, |mask, (i, crew)| mask | ((crew.ok as u8) << i));
        crate::lan::WorldSnapshot {
            seq: 0,
            act: self.act.id,
            player: tank(&self.player),
            enemies: self.enemies.iter().map(tank).collect(),
            engine_on: self.engine_on,
            hatch_open: self.hatch_open,
            breech: match self.breech {
                Breech::Loaded => 0,
                Breech::Spent => 1,
                Breech::Empty => 2,
            },
            rounds_spent: self.rounds_spent,
            he_loaded: self.he_loaded,
            fire: self.fire,
            module_mask,
            crew_mask,
            act_complete: self.act_complete,
            armor_scars: self.armor_scars.scars().to_vec(),
            building: self
                .modular_building
                .as_ref()
                .map(|building| building.export_snapshot(self.act.id)),
        }
    }

    /// Reconcile a client prediction to the host. Invalid/non-finite tank records are ignored as a
    /// unit; a malformed LAN packet can never poison physics with NaNs.
    pub fn apply_net_snapshot(
        &mut self,
        snapshot: &crate::lan::WorldSnapshot,
        renderer: &mut Renderer,
    ) {
        fn apply(dst: &mut Tank, src: crate::lan::NetTankState) {
            let values = [
                src.pos[0],
                src.pos[1],
                src.pos[2],
                src.heading,
                src.speed,
                src.turret_yaw,
                src.gun_pitch,
                src.reload,
                src.hp,
            ];
            if !values.iter().all(|value| value.is_finite()) {
                return;
            }
            dst.pos = Vec3::from_array(src.pos);
            dst.heading = src.heading;
            dst.speed = src.speed;
            dst.turret_yaw = src.turret_yaw;
            dst.gun_pitch = src.gun_pitch;
            dst.reload = src.reload.max(0.0);
            dst.hp = src.hp.clamp(0.0, tank::MAX_HP);
            dst.alive = src.alive;
        }
        apply(&mut self.player, snapshot.player);
        for (i, src) in snapshot.enemies.iter().copied().enumerate() {
            if i >= self.enemies.len() {
                break;
            }
            let was_alive = self.enemies[i].alive;
            apply(&mut self.enemies[i], src);
            if self.enemies[i].alive {
                // A client can briefly predict a kill before the authoritative snapshot arrives.
                // Remove that speculative wreck completely instead of leaving a burning ghost.
                self.wrecks[i] = Wreck::default();
            } else if was_alive {
                // The host owns the kill result. Give late-arriving remote kills an immediate,
                // deterministic burning wreck; subsequent snapshots keep the dead tank aligned.
                self.wrecks[i] = Wreck {
                    kind: WreckKind::Burn,
                    burning: true,
                    ..Wreck::default()
                };
            }
        }
        self.engine_on = snapshot.engine_on;
        self.hatch_open = snapshot.hatch_open;
        self.breech = match snapshot.breech {
            0 => Breech::Loaded,
            1 => Breech::Spent,
            _ => Breech::Empty,
        };
        self.rounds_spent = snapshot.rounds_spent;
        self.he_loaded = snapshot.he_loaded;
        self.fire = snapshot.fire.clamp(0.0, 1.0);
        for (i, module) in self.modules.iter_mut().enumerate() {
            module.functional = snapshot.module_mask & (1 << i) != 0;
        }
        for (i, crew) in self.crew.iter_mut().enumerate() {
            crew.ok = snapshot.crew_mask & (1 << i) != 0;
        }
        self.act_complete = snapshot.act_complete;
        self.armor_scars =
            crate::armor_damage::ArmorField::from_scars(snapshot.armor_scars.clone());

        if snapshot.act == self.act.id {
            let imported = match (&mut self.modular_building, &snapshot.building) {
                (Some(building), Some(saved)) => {
                    Some(building.replace_from_snapshot(snapshot.act, saved))
                }
                _ => None,
            };
            match imported {
                Some(Ok(())) => self.reconcile_modular_building_state_quiet(renderer),
                Some(Err(error)) => {
                    eprintln!("[lan] ignored invalid authoritative building state: {error}")
                }
                None => {}
            }
        }
    }

    pub fn debug_engage_all(&mut self) {
        for i in 0..self.enemies.len() {
            if self.enemies[i].alive {
                self.stealth.spotted[i] = true;
                self.stealth.meters[i] = 1.0;
            }
        }
        let pos = self.player.center();
        for p in self.stealth.platoons.iter_mut() {
            if p.state != stealth::AlertState::Eliminated {
                p.state = stealth::AlertState::Engaged;
                p.pending = false;
                p.last_known = pos;
            }
        }
    }

