    #[test]
    fn rtt_budget_one_prioritizes_visible_then_trickles_stalest() {
        let alignments = [-0.4, 0.93, 0.2, 0.55];
        let mut last = [2, 6, 1, 4];
        assert_eq!(rtt_priority_pick(&alignments, &last, 6), Some(1));
        // Every eighth frame ignores gaze once and services the oldest background pane.
        assert_eq!(rtt_priority_pick(&alignments, &last, 7), Some(2));
        last[2] = 8;
        assert_eq!(rtt_priority_pick(&alignments, &last, 15), Some(0));
        assert_eq!(rtt_priority_pick(&[], &[], 0), None);
        assert_eq!(rtt_priority_pick(&[1.0], &[0, 1], 0), None);
    }

