    #[test]
    fn rtt_viewer_gate_accounts_for_every_couch_station_not_only_keyboard() {
        // P1 may have moved to the gunner's post; a living Loader viewport still sees its roof
        // periscope and therefore keeps the rolling atlas alive.
        assert!(rtt_has_inside_viewer(
            true,
            false,
            true,
            Station::Gunner,
            false,
        ));
        // An exposed Commander alone cannot see an interior eyepiece.
        assert!(!rtt_has_inside_viewer(
            true,
            true,
            false,
            Station::Commander,
            true,
        ));
        // Solo behavior remains station-local.
        assert!(rtt_has_inside_viewer(
            false,
            false,
            false,
            Station::Loader,
            false,
        ));
        assert!(!rtt_has_inside_viewer(
            false,
            true,
            true,
            Station::Driver,
            false,
        ));
    }

    #[test]
    fn act2_channel_rejects_fording_but_keeps_the_single_bridge_open() {
        let z = 0.0;
        let channel_x = act2_channel_center_x(z);
        let east_bank = Vec2::new(channel_x + 30.0, z);
        let attempted_ford = Vec2::new(channel_x + 4.0, z);
        let blocked = constrain_act2_channel_step(east_bank, attempted_ford);
        assert!((blocked.x - (channel_x + ACT2_CHANNEL_NO_GO_HALF_M)).abs() < 1.0e-4);
        assert_eq!(
            blocked.y, attempted_ford.y,
            "movement along the bank is retained"
        );
        assert!(!act2_step_crosses_bridge(
            Vec2::new(channel_x + 30.0, z),
            Vec2::new(channel_x - 30.0, z)
        ));

        let bridge_step = Vec2::new(30.0, ACT2_BRIDGE_Z_M);
        let across_bridge = Vec2::new(-30.0, ACT2_BRIDGE_Z_M);
        assert_eq!(
            constrain_act2_channel_step(bridge_step, across_bridge),
            across_bridge
        );
        assert!(act2_step_crosses_bridge(bridge_step, across_bridge));
    }

