    #[test]
    fn cubic_blood_density_scales_to_horror_burst_without_unbounded_slots() {
        assert_eq!(blood_body_count(0.20), 96);
        assert_eq!(blood_body_count(1.65), N_BLOOD_CUBES);
        let samples = [0.20, 0.45, 0.80, 1.20, 1.65].map(blood_body_count);
        assert_eq!(samples, [96, 176, 448, 816, 1024]);
        assert!(samples.windows(2).all(|pair| pair[0] <= pair[1]));
        assert_eq!(N_BLOOD_CUBES, N_BLOOD_BATCHES * BLOOD_GRAINS_PER_BATCH);
        assert_eq!(BLOOD_GRAIN_SIZE, 0.022);
        assert!(
            BLOOD_GRAIN_SIZE <= 0.024,
            "droplets must stay uniformly small"
        );
        assert_eq!(
            N_BLOOD_STAINS,
            COUCH_CREW_ROLES.len() * BLOOD_STAINS_PER_CASUALTY
        );

        // Strict 1:1 contract: one prototype instance is one visible cube and one BloodCube state.
        // There is no packed satellite geometry hiding multiple visuals inside a rigid body.
        let mesh = blood_grain_mesh([96, 7, 5]);
        assert_eq!(mesh.indices.len(), 36);
        assert_eq!(mesh.vertices.len(), 24);
        assert_eq!(mesh.indices.len() / 36, 1);
        assert_eq!(N_BLOOD_CUBES * (mesh.indices.len() / 36), 1024);
        assert_eq!(mesh.min, Vec3::splat(-0.5));
        assert_eq!(mesh.max, Vec3::splat(0.5));
        assert_eq!(mesh.metallic_factor, 0.0);
        assert!(
            mesh.roughness_factor <= 0.10,
            "fresh grains must read as wet"
        );
    }

    #[test]
    fn live_hot_fragment_lifetime_and_light_follow_the_physical_chip_pool() {
        let clean = fragment_shower_profile(true, 0.45, 88.0, 410.0, 0.0);
        let catastrophic = fragment_shower_profile(true, 1.65, 122.0, 620.0, 156.0);
        assert!(clean.fragment_life >= 3.20);
        assert!(catastrophic.fragment_life >= 5.70);
        assert!(catastrophic.fragment_life > clean.fragment_life);

        let hot = [
            HotFragment {
                active: true,
                frame: BloodFrame::Turret,
                pos: Vec3::new(-0.24, 1.10, 0.05),
                size: 0.008,
                age: 0.20,
                life: 6.0,
                seed: 11,
                ..HotFragment::default()
            },
            HotFragment {
                active: true,
                frame: BloodFrame::Turret,
                pos: Vec3::new(0.31, 1.26, -0.08),
                size: 0.006,
                age: 0.20,
                life: 6.0,
                seed: 29,
                ..HotFragment::default()
            },
        ];
        let hot_light =
            hot_fragment_aggregate_light(&hot, BloodFrame::Turret, Mat4::IDENTITY).unwrap();
        for fragment in &hot {
            let cube_radius = fragment.size * 0.5 * 3.0f32.sqrt();
            assert!(
                fragment.pos.distance(hot_light.pos) + cube_radius
                    <= hot_light.source_radius + 1.0e-6,
                "the clustered source sphere must enclose every luminous cube"
            );
        }

        let cool = hot.map(|fragment| HotFragment {
            age: 4.8,
            ..fragment
        });
        let cool_light =
            hot_fragment_aggregate_light(&cool, BloodFrame::Turret, Mat4::IDENTITY).unwrap();
        assert!(cool_light.radiant_intensity < hot_light.radiant_intensity * 0.10);
        assert!(cool_light.color.y < hot_light.color.y);

        let retired = hot.map(|fragment| HotFragment {
            active: false,
            ..fragment
        });
        assert!(
            hot_fragment_aggregate_light(&retired, BloodFrame::Turret, Mat4::IDENTITY).is_none()
        );
        assert!(hot_fragment_aggregate_light(&hot, BloodFrame::Hull, Mat4::IDENTITY).is_none());
    }

    #[test]
    #[cfg(any())] // retired with the cfg(any()) legacy penetration-FX/spall path (HOT_FRAGMENT_TAIL_MIN_LENGTH, HOT_FRAGMENT_VISUAL_CUBE_SIZE, MICRO_SPARK_STAGE_CAPACITY, N_MICRO_SPARKS, PENETRATION_BURST_VISUAL_MAX_DUR, PENETRATION_BURST_VISUAL_MAX_SCALE, PenetrationFxKind, penetration_fx_profile)
    fn penetration_fx_scales_from_clean_hole_to_full_catastrophic_shower() {
        // Representative event ladder: distant defeat, marginal 88 mm hole, a close-range T-34
        // side penetration, filled-shell burst, and an ammunition catastrophe.
        let bounce = penetration_fx_profile(false, 0.18, 76.2, 0.0, 0.0, 0, 0, false, false);
        let clean = penetration_fx_profile(true, 0.45, 88.0, 410.0, 0.0, 0, 0, false, false);
        let t34_side = penetration_fx_profile(true, 1.05, 85.0, 520.0, 0.0, 2, 1, false, false);
        let explosive = penetration_fx_profile(true, 1.10, 122.0, 560.0, 156.0, 2, 1, false, true);
        let catastrophic =
            penetration_fx_profile(true, 1.65, 122.0, 620.0, 156.0, 3, 1, true, true);
        let profiles = [clean, t34_side, explosive, catastrophic];

        assert_eq!(bounce.kind, PenetrationFxKind::Deflection);
        assert_eq!(
            bounce,
            penetration_fx_profile(false, 0.18, 76.2, 0.0, 0.0, 0, 0, false, false),
            "profile selection and tuning must be replay deterministic"
        );
        assert_eq!(clean.kind, PenetrationFxKind::CleanKinetic);
        assert_eq!(t34_side.kind, PenetrationFxKind::SpallHeavy);
        assert_eq!(explosive.kind, PenetrationFxKind::Explosive);
        assert_eq!(catastrophic.kind, PenetrationFxKind::Catastrophic);
        assert_eq!(bounce.fragment_count, 0);
        assert_eq!(bounce.micro_spark_count, 0);
        assert_eq!(bounce.light_radius, 0.0);
        assert_eq!(catastrophic.fragment_count, N_HOT_FRAGMENTS);
        assert_eq!(catastrophic.micro_spark_count, N_MICRO_SPARKS);
        assert!(profiles
            .windows(2)
            .all(|pair| pair[0].fragment_count < pair[1].fragment_count));
        assert!(profiles
            .windows(2)
            .all(|pair| pair[0].micro_spark_count < pair[1].micro_spark_count));
        assert!(profiles
            .windows(2)
            .all(|pair| pair[0].fragment_life < pair[1].fragment_life));
        assert!(profiles
            .windows(2)
            .all(|pair| pair[0].light_radius < pair[1].light_radius));
        assert!(profiles
            .windows(2)
            .all(|pair| pair[0].light_dur < pair[1].light_dur));
        for profile in profiles {
            assert!(profile.fragment_count <= N_HOT_FRAGMENTS);
            assert!(profile.fragment_count <= HOT_FRAGMENT_STAGE_CAPACITY);
            assert_eq!(profile.fragment_count % N_HOT_FRAGMENT_BATCHES, 0);
            assert!(profile.micro_spark_count <= N_MICRO_SPARKS);
            assert!(profile.micro_spark_count <= MICRO_SPARK_STAGE_CAPACITY);
            assert_eq!(profile.micro_spark_count % 8, 0);
            let micro_ratio = profile.micro_spark_count as f32 / profile.fragment_count as f32;
            assert!((3.0..=6.0).contains(&micro_ratio));
            assert!(profile.fragment_life >= 2.8);
            assert!(profile.beam_dur >= 6.0 / 24.0);
            assert!((0.075..=0.14).contains(&profile.flash_dur));
            assert!(profile.speed_max < 9.0, "24-fps paths must remain readable");
        }
        assert!(explosive.light_radius >= 4.0);
        assert!(catastrophic.light_radius >= 4.7);
        assert!(catastrophic.light_hold * 24.0 >= 17.0);
        assert!(catastrophic.light_tail > clean.light_tail * 5.0);
        assert_eq!(HOT_FRAGMENT_STAGE_CAPACITY, N_HOT_FRAGMENTS);
        assert_eq!(N_HOT_FRAGMENTS, 160);
        assert_eq!(MICRO_SPARK_STAGE_CAPACITY, N_MICRO_SPARKS);
        assert_eq!(N_MICRO_SPARKS, 768);
        assert!(PENETRATION_BURST_VISUAL_MAX_DUR <= 0.18);
        assert!(PENETRATION_BURST_VISUAL_MAX_SCALE * 0.70 < 0.25);

        let mesh = hot_fragment_mesh([255, 244, 210]);
        assert_eq!(
            mesh.indices.len(),
            36,
            "one instance is exactly one steel chip"
        );
        assert_eq!(mesh.vertices.len(), 24);
        assert!(mesh.metallic_factor > 0.7);

        let flying = HotFragment {
            active: true,
            size: 0.017,
            vel: Vec3::new(7.5, 2.0, -3.0),
            ang: Vec3::new(0.4, 1.7, 2.6),
            ..HotFragment::default()
        };
        let (flying_scale, _) = hot_fragment_render_pose(&flying);
        assert_eq!(flying_scale, Vec3::splat(HOT_FRAGMENT_VISUAL_CUBE_SIZE));
        assert!(HOT_FRAGMENT_VISUAL_CUBE_SIZE < flying.size * 0.5);
        let (settled_scale, _) = hot_fragment_render_pose(&HotFragment {
            settled: true,
            ..flying
        });
        assert_eq!(settled_scale, Vec3::splat(HOT_FRAGMENT_VISUAL_CUBE_SIZE));

        let (tail_scale, tail_rot, tail_pos) = hot_fragment_tail_pose(&flying).unwrap();
        assert!(tail_scale.x < HOT_FRAGMENT_VISUAL_CUBE_SIZE * 0.5);
        assert_eq!(tail_scale.x, tail_scale.y);
        assert!(
            (HOT_FRAGMENT_TAIL_MIN_LENGTH..=HOT_FRAGMENT_TAIL_MAX_LENGTH).contains(&tail_scale.z)
        );
        let dir = flying.vel.normalize();
        assert!((tail_rot * Vec3::Z).dot(dir) > 0.999);
        let tail_front = tail_pos + dir * tail_scale.z * 0.5;
        let cube_back = flying.pos - dir * HOT_FRAGMENT_VISUAL_CUBE_SIZE * 0.5;
        assert!(tail_front.distance(cube_back) < 1.0e-5);
        assert!(hot_fragment_tail_pose(&HotFragment {
            settled: true,
            ..flying
        })
        .is_none());
        assert!(hot_fragment_tail_pose(&HotFragment {
            vel: Vec3::splat(0.1),
            ..flying
        })
        .is_none());
    }

    #[test]
    #[cfg(any())] // retired with the cfg(any()) micro-spark layer (integrate_micro_spark)
    fn micro_sparks_are_tiny_fast_visuals_and_retire_without_physical_state() {
        let mut spark = MicroSpark {
            active: true,
            frame: BloodFrame::Turret,
            pos: Vec3::new(0.2, 1.5, -0.1),
            vel: Vec3::new(11.0, 1.2, 3.0),
            size: 0.002,
            age: 0.0,
            life: 0.80,
            seed: 0x51A4_7701,
        };
        let origin = spark.pos;
        let (head_scale, _) = micro_spark_render_pose(&spark);
        assert_eq!(head_scale, Vec3::splat(0.002));
        assert!((0.001..=0.003).contains(&spark.size));
        let (tail_scale, tail_rot, tail_pos) = micro_spark_tail_pose(&spark).unwrap();
        assert!(tail_scale.x < spark.size * 0.5);
        assert_eq!(tail_scale.x, tail_scale.y);
        assert!((MICRO_SPARK_TAIL_MIN_LENGTH..=MICRO_SPARK_TAIL_MAX_LENGTH).contains(&tail_scale.z));
        let dir = spark.vel.normalize();
        assert!((tail_rot * Vec3::Z).dot(dir) > 0.999);
        assert!(tail_pos.dot(dir) < spark.pos.dot(dir));

        assert_eq!(micro_spark_heat_stage(&spark), 0);
        for _ in 0..6 {
            integrate_micro_spark(&mut spark, 0.05);
        }
        assert!(spark.active && spark.pos.distance(origin) > 1.0);
        assert_eq!(micro_spark_heat_stage(&spark), 1);
        for _ in 0..6 {
            integrate_micro_spark(&mut spark, 0.05);
        }
        assert_eq!(micro_spark_heat_stage(&spark), 2);
        for _ in 0..20 {
            integrate_micro_spark(&mut spark, 0.05);
        }
        assert!(!spark.active);
        assert!(micro_spark_tail_pose(&spark).is_none());
    }

    #[test]
    #[cfg(any())] // retired with the cfg(any()) penetration_fx_profile / PenetrationPulse light envelope
    fn penetration_furnace_envelope_holds_then_releases_without_leaking() {
        let profile = penetration_fx_profile(true, 1.65, 122.0, 620.0, 156.0, 3, 1, true, true);
        let pulse = PenetrationPulse {
            active: true,
            kind: profile.kind,
            light_radius: profile.light_radius,
            light_peak: profile.light_peak,
            light_tail: profile.light_tail,
            light_hold: profile.light_hold,
            light_dur: profile.light_dur,
            ..PenetrationPulse::default()
        };
        let impact = penetration_light_envelope(0.0, &pulse);
        let furnace = penetration_light_envelope(0.40, &pulse);
        let release = penetration_light_envelope(profile.light_dur - 0.08, &pulse);
        assert!((impact.0 - profile.light_peak).abs() < 1.0e-5);
        assert!((impact.1 - profile.light_radius * 0.48).abs() < 1.0e-5);
        assert!(furnace.0 >= profile.light_tail);
        assert!((furnace.1 - profile.light_radius).abs() < 1.0e-5);
        assert!(release.0 > 0.0 && release.0 < furnace.0);
        let (impact_flash, _, _) = penetration_light_terms(0.0, &pulse);
        let (flash_at_80ms, _, _) = penetration_light_terms(0.080, &pulse);
        let (late_flash, late_furnace, _) = penetration_light_terms(3.0 / 24.0, &pulse);
        assert_eq!(impact_flash, profile.light_peak);
        assert!(flash_at_80ms < profile.light_peak * 0.10);
        assert!(late_flash < profile.light_peak * 0.03);
        assert!(late_furnace > late_flash);

        let (impact_surface, impact_air) = penetration_light_colors(0.0, &pulse);
        let (tail_surface, tail_air) = penetration_light_colors(0.40, &pulse);
        assert!(impact_surface.y <= 0.31 && impact_surface.z <= 0.045);
        assert!(impact_air.y <= 0.22 && impact_air.z <= 0.025);
        assert!(tail_surface.y < impact_surface.y * 0.25);
        assert!(tail_air.y < impact_air.y * 0.25);
        assert_eq!(
            penetration_light_envelope(profile.light_dur, &pulse),
            (0.0, 0.0)
        );
    }

    #[test]
    fn hot_fragment_cooling_bounce_and_collision_buffers_stay_bounded() {
        let mut fragment = HotFragment {
            active: true,
            frame: BloodFrame::Turret,
            life: 4.0,
            seed: 0xBEEF,
            ..HotFragment::default()
        };
        assert_eq!(hot_fragment_heat_stage(&fragment), 0);
        fragment.age = 0.16;
        assert_eq!(hot_fragment_heat_stage(&fragment), 1);
        fragment.age = 0.80;
        assert_eq!(hot_fragment_heat_stage(&fragment), 2);
        fragment.age = 3.40;
        assert_eq!(hot_fragment_heat_stage(&fragment), 3);

        let budgets: Vec<u8> = (0..512).map(hot_fragment_bounce_budget).collect();
        assert!(budgets.iter().all(|budget| (7..=11).contains(budget)));
        assert!(budgets.contains(&7) && budgets.contains(&11));

        let mut events = Vec::with_capacity(MAX_HOT_FRAGMENT_COLLISIONS_PER_FRAME);
        let mut total = 0usize;
        let mut impact = HotFragment {
            active: true,
            frame: BloodFrame::Turret,
            pos: Vec3::new(TURRET_BLOOD_WALL_R - 0.01, 1.6, 0.0),
            vel: Vec3::new(6.0, 0.0, 0.0),
            size: 0.015,
            life: 4.0,
            seed: 99,
            ..HotFragment::default()
        };
        for _ in 0..(MAX_HOT_FRAGMENT_COLLISIONS_PER_FRAME + 20) {
            impact.vel = Vec3::new(6.0, 0.0, 0.0);
            hot_fragment_bounce(
                &mut impact,
                Vec3::NEG_X,
                0.82,
                0.96,
                &mut events,
                &mut total,
            );
        }
        assert_eq!(events.len(), MAX_HOT_FRAGMENT_COLLISIONS_PER_FRAME);
        assert_eq!(total, MAX_HOT_FRAGMENT_COLLISIONS_PER_FRAME + 20);
        assert!(events.iter().all(|event| event.turret_local));
        assert!(events.iter().all(|event| event.speed >= 6.0));
        assert!(
            impact.vel.length_squared() >= 6.0f32.powi(2) * 0.65,
            "even a head-on wall strike must retain most of the cube's kinetic energy"
        );
    }

