    #[test]
    fn hot_fragment_audio_batch_is_deterministic_strongest_two() {
        use crate::acoustics::{FragmentCollisionParams, FragmentMaterial};

        let make_contacts = || {
            (0..40u32)
                .rev()
                .map(|seed| FragmentCollisionParams {
                    speed_mps: seed as f32,
                    material: FragmentMaterial::ArmorPlate,
                    bearing_deg: (seed * 17) as f32,
                    distance_m: 1.0 + seed as f32 * 0.01,
                    seed,
                })
                .chain([FragmentCollisionParams {
                    speed_mps: f32::NAN,
                    material: FragmentMaterial::BreechBlock,
                    bearing_deg: 0.0,
                    distance_m: 1.0,
                    seed: 999,
                }])
                .collect::<Vec<_>>()
        };
        let mut a = make_contacts();
        let mut b = make_contacts();
        b.reverse();
        bound_hot_fragment_audio_contacts(&mut a);
        bound_hot_fragment_audio_contacts(&mut b);

        assert_eq!(a.len(), MAX_HOT_FRAGMENT_AUDIO_CONTACTS);
        assert_eq!(a.first().unwrap().speed_mps, 39.0);
        assert_eq!(a.last().unwrap().speed_mps, 38.0);
        assert_eq!(MAX_HOT_FRAGMENT_AUDIO_CONTACTS, 2);
        assert_eq!(HOT_FRAGMENT_AUDIO_DING_BUDGET, 2);
        assert_eq!(HOT_FRAGMENT_AUDIO_WHIZZ_BUDGET, 1);
        let signature = |contacts: &[FragmentCollisionParams]| {
            contacts
                .iter()
                .map(|contact| (contact.speed_mps.to_bits(), contact.seed))
                .collect::<Vec<_>>()
        };
        assert_eq!(signature(&a), signature(&b));
    }

