    #[test]
    fn couch_living_peer_can_take_over_a_kia_post_without_reviving_the_victim() {
        use crate::lan::{LanRole, RoleInput};
        let mut frame = four_person_couch_frame();
        let kia = vec![33];
        sanitize_couch_crew_frame(&mut frame, &kia);

        // Loader 44 leaves his original post and takes Driver. The dead peer stays dead; the Driver
        // body/authority now belongs to the surviving identity and Loader becomes the next vacancy.
        frame.roster[LanRole::Loader as usize] = EMPTY_CREW_PEER;
        frame.inputs[LanRole::Loader as usize] = RoleInput::default();
        frame.roster[LanRole::Driver as usize] = 44;
        frame.inputs[LanRole::Driver as usize] = RoleInput {
            drive: 1.0,
            post: LanRole::Driver,
            ..RoleInput::default()
        };
        // A subsequent game frame sanitizes again. It must key mortality by stable peer ID, not by
        // the post where the casualty happened, or the living takeover would be erased too.
        sanitize_couch_crew_frame(&mut frame, &kia);
        let bodies = couch_crew_bodies(frame, &kia, &NO_COUCH_IDENTITIES);
        assert!(kia.contains(&33), "takeover must never revive the casualty");
        let mut living: Vec<u32> = bodies.iter().map(|body| body.casualty.peer_id).collect();
        living.sort_unstable();
        assert_eq!(living, vec![11, 22, 44]);
        assert!(bodies
            .iter()
            .any(|body| { body.casualty.peer_id == 44 && body.casualty.role == LanRole::Driver }));
        assert!(!bodies
            .iter()
            .any(|body| body.casualty.role == LanRole::Loader));
    }

