    #[test]
    fn chambered_round_is_counted_once_and_never_free() {
        let mut taken = [false, false, true];
        assert_eq!(remaining_main_gun_rounds(&taken, Breech::Loaded), 3);

        // Firing consumes the chamber immediately; the two rack rounds remain.
        assert_eq!(remaining_main_gun_rounds(&taken, Breech::Spent), 2);

        // Reloading moves one physical rack round into the chamber without changing the total.
        taken[0] = true;
        assert_eq!(remaining_main_gun_rounds(&taken, Breech::Loaded), 2);
    }

